pandasComparison.sql:
SELECT customer_id, amount,
       amount * 0.9 AS discounted_amount
FROM orders;

SELECT u.user_id, u.user_name, o.order_id, o.amount
FROM users u
LEFT JOIN orders o ON u.user_id = o.user_id;

SELECT order_id, amount
FROM orders
WHERE amount > (SELECT AVG(amount) FROM orders);

SELECT DATE_FORMAT(order_date,'%Y-%m') month, SUM(amount) sales
FROM orders
GROUP BY DATE_FORMAT(order_date,'%Y-%m');

sqlExamples.sql:
SELECT user_id,
       CONCAT(SUBSTRING(phone,1,3), '****', SUBSTRING(phone,8,4)) AS masked_phone
FROM users;

WITH paid_orders AS (
  SELECT * FROM orders WHERE status = 'paid'
)
SELECT user_id, SUM(amount) AS total_spend
FROM paid_orders
GROUP BY user_id;

SELECT COUNT(DISTINCT user_id) AS buyers, SUM(amount) AS gmv
FROM orders
WHERE status = 'paid';

WITH user_spend AS (
  SELECT user_id, SUM(amount) total_spend
  FROM orders WHERE status='paid' GROUP BY user_id
)
SELECT *, RANK() OVER (ORDER BY total_spend DESC) spend_rank
FROM user_spend;

